  ('a8734e8a-b774-5363-92f5-3a5269d908c4', 'e91b8b9a-54e8-55a1-8412-d3ade3da0b53', 'Weight Management — First Consultation', 'weight-management-first', 'CONSULTATION', 'Full intake and clinical screening. Seen in person by a pharmacist.', null, '[]'::jsonb)
