insert into form_version (id, organisation_id, service_id, version, schema, published_at) values
  ('c50694a1-7430-5579-b950-f07903d57a1a', 'e91b8b9a-54e8-55a1-8412-d3ade3da0b53', 'a8734e8a-b774-5363-92f5-3a5269d908c4', 1, '{"schemaVersion":1,"title":"Weight Management — First Consultation","description":"Please complete this before your appointment. A pharmacist will go through it with you in person.","numberQuestions":true,"estimatedMinutes":10,"consentClauses":[{"id":"risks","text":"I have received information on the risks and benefits of the medicine, and I have had the opportunity to ask questions."},{"id":"accurate","text":"The medical information I have provided is true and accurate to the best of my knowledge, and I consent to the medicine being supplied."},{"id":"reliance","text":"I understand that the supply of this medicine is based on the information I have given, and that if it is inaccurate it could negatively affect my treatment."},{"id":"appointment","text":"I understand that I can make an appointment to see a pharmacist in person at any time to discuss my treatment."},{"id":"storage","text":"I understand that my personal information — name, surname, email, telephone, date of birth, address and GP details — will be securely stored and processed in line with data protection regulations."},{"id":"transmission","text":"I authorise the collection, storage, and secure transmission of my information for the purposes mentioned above."},{"id":"gp","text":"I acknowledge that my GP will be notified of any prescription issued."},{"id":"rights","text":"I understand I can speak to a member of staff about any queries regarding my consultation or the processing of my personal data, by contacting the pharmacy."}],"clinicianDeclarations":[{"id":"accurate","text":"I confirm the patient has provided accurate information and disclosed all medical conditions and allergies."},{"id":"leaflet","text":"I confirm I have provided a patient information leaflet and discussed as required."},{"id":"side-effects","text":"I confirm I have advised the patient on possible side effects and their management."},{"id":"pregnancy-suspected","text":"I have made the patient aware they should discontinue treatment and contact their supplier or GP if they suspect pregnancy."},{"id":"pregnancy-planned","text":"I have made the patient aware they should contact their supplier if planning pregnancy, as treatment must be discontinued."},{"id":"contraception","text":"I confirm the patient has been advised regarding contraception interactions and risks related to delayed gastric emptying."},{"id":"insulin","text":"I confirm the patient has received GP advice if also taking insulin or sulfonylureas, with monitoring in place."}],"steps":[{"id":"measurements","title":"Your measurements","description":"Enter these in whichever units you know them in — we convert them.","fields":[{"id":"height","type":"measurement","label":"Height","measurementKind":"height","required":true},{"id":"weight","type":"measurement","label":"Current weight","measurementKind":"weight","required":true},{"id":"waist","type":"measurement","label":"Waist circumference","measurementKind":"length","required":true},{"id":"bmi","type":"derived","label":"Calculated BMI","calculation":"bmi","calculationInputs":["weight","height"]}]},{"id":"medical-history","title":"Medical history","description":"These questions decide whether this treatment is safe for you.","fields":[{"id":"contraindications","type":"checkboxGroup","label":"Do you have any of the following conditions?","helpText":"Tick all that apply, or tick \"None of the above\".","required":true,"presentation":"checkList","options":[{"value":"heart_failure","label":"Severe heart failure"},{"value":"retinopathy","label":"Diabetic retinopathy"},{"value":"pancreatitis","label":"Pancreatitis (current or previous)"},{"value":"gastroparesis","label":"Gastroparesis"},{"value":"ibd","label":"Ulcerative colitis or Crohn''s disease"},{"value":"thyroid_cancer","label":"History or family history of thyroid cancer"},{"value":"men2","label":"History or family history of MEN2"},{"value":"cancer","label":"Any cancer, chemotherapy or radiotherapy"},{"value":"none","label":"None of the above"}]},{"id":"gallbladder","type":"yesNo","label":"Do you have gallbladder or bile duct issues?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"gallbladderDetail","type":"checkboxGroup","label":"Could you tell us a little more?","required":true,"presentation":"checkList","options":[{"value":"current","label":"Currently experiencing gallstones"},{"value":"previous","label":"Previously experienced gallstones"},{"value":"removed","label":"I had my gallbladder removed"},{"value":"other","label":"Other"}]},{"id":"gallbladderOther","type":"longText","label":"Please give any other details"}]}]},{"id":"liver","type":"yesNo","label":"Do you have liver impairment?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"liverDetail","type":"checkboxGroup","label":"Which applies to you?","required":true,"presentation":"checkList","options":[{"value":"nafld","label":"Non-alcoholic fatty liver disease"},{"value":"nash","label":"NASH"},{"value":"moderate_severe","label":"Moderate or severe liver impairment"},{"value":"other","label":"Other"}]},{"id":"liverOther","type":"longText","label":"Please give any other details"}]}]},{"id":"diabetes","type":"select","label":"Do you have diabetes?","required":true,"presentation":"radioList","options":[{"value":"no","label":"No"},{"value":"prediabetes","label":"Pre-diabetes, or diet-controlled"},{"value":"medicated","label":"Yes — and I take medicine for it"}]},{"id":"weightConditions","type":"multiSelect","label":"Do you have any weight-related conditions?","helpText":"Select all that apply.","presentation":"chips","options":[{"value":"none","label":"None of the above"},{"value":"depression","label":"Depression linked to weight"},{"value":"reflux","label":"Acid reflux / GORD"},{"value":"hypertension","label":"High blood pressure"},{"value":"ed","label":"Erectile dysfunction"},{"value":"cvd","label":"Cardiovascular disease"},{"value":"osteoarthritis","label":"Knee or hip osteoarthritis"},{"value":"asthma","label":"Asthma"},{"value":"copd","label":"COPD"},{"value":"sleep_apnoea","label":"Obstructive sleep apnoea"},{"value":"cholesterol","label":"High cholesterol"},{"value":"pcos","label":"PCOS"},{"value":"other","label":"Other"}],"reveals":[{"whenValue":"other","fields":[{"id":"weightConditionsOther","type":"longText","label":"Please tell us more"}]}]}]},{"id":"habits-safety","title":"Habits and safety","description":"Please answer honestly — nothing here is judged, and it changes what is safe to supply.","fields":[{"id":"madeSick","type":"yesNo","label":"Have you ever made yourself sick to lose weight?","required":true,"presentation":"pills"},{"id":"laxatives","type":"yesNo","label":"Have you ever taken laxatives to lose weight?","required":true,"presentation":"pills"},{"id":"controlEating","type":"yesNo","label":"Do you struggle to control your eating?","required":true,"presentation":"pills"},{"id":"eatingDisorder","type":"yesNo","label":"Have you ever been diagnosed with an eating disorder?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"eatingDisorderDetail","type":"longText","label":"Please tell us more","required":true}]}]},{"id":"otherMeds","type":"yesNo","label":"Are you taking any other medication?","helpText":"Including anything bought over the counter.","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"otherMedsDetail","type":"longText","label":"Which medicines, and what dose?","required":true}]}]},{"id":"allergies","type":"yesNo","label":"Do you have any allergies?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"allergiesDetail","type":"longText","label":"What are you allergic to, and what happens?","required":true}]}]},{"id":"recentSurgery","type":"yesNo","label":"Have you had surgery in the last 3 months?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"recentSurgeryDetail","type":"longText","label":"What surgery, and when?","required":true}]}]}]},{"id":"request","title":"What you are asking for","fields":[{"id":"recentWeightLossMeds","type":"select","label":"Have you taken any weight loss medication in the last 2 weeks?","required":true,"presentation":"radioList","options":[{"value":"none","label":"Not currently taking any"},{"value":"wegovy","label":"Wegovy"},{"value":"mounjaro","label":"Mounjaro"},{"value":"ozempic","label":"Ozempic"},{"value":"other","label":"Other"}],"reveals":[{"whenValue":"other","fields":[{"id":"recentMedsOther","type":"shortText","label":"Which medicine?","required":true}]}]},{"id":"everUsedWeightLossMeds","type":"yesNo","label":"Have you ever used weight loss medication before?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"previousMeds","type":"multiSelect","label":"Which have you used?","required":true,"presentation":"chips","options":[{"value":"wegovy","label":"Wegovy"},{"value":"mounjaro","label":"Mounjaro"},{"value":"saxenda","label":"Saxenda"},{"value":"orlistat","label":"Xenical / Orlistat"},{"value":"ozempic","label":"Ozempic"},{"value":"other","label":"Other"}]},{"id":"previousMedsDetail","type":"longText","label":"How did you get on with them?"}]}]},{"id":"requestedMedicine","type":"select","label":"Which medicine and strength are you requesting?","required":true,"presentation":"dropdown","storeMetadataAs":"requestedMedicineDetail","options":[{"value":"mounjaro_2.5mg","label":"Mounjaro 2.5mg","metadata":{"medicine":"Mounjaro","strength":"2.5mg","ladderIndex":0}},{"value":"mounjaro_5mg","label":"Mounjaro 5mg","metadata":{"medicine":"Mounjaro","strength":"5mg","ladderIndex":1}},{"value":"mounjaro_7.5mg","label":"Mounjaro 7.5mg","metadata":{"medicine":"Mounjaro","strength":"7.5mg","ladderIndex":2}},{"value":"mounjaro_10mg","label":"Mounjaro 10mg","metadata":{"medicine":"Mounjaro","strength":"10mg","ladderIndex":3}},{"value":"mounjaro_12.5mg","label":"Mounjaro 12.5mg","metadata":{"medicine":"Mounjaro","strength":"12.5mg","ladderIndex":4}},{"value":"mounjaro_15mg","label":"Mounjaro 15mg","metadata":{"medicine":"Mounjaro","strength":"15mg","ladderIndex":5}},{"value":"wegovy_0.25mg","label":"Wegovy 0.25mg","metadata":{"medicine":"Wegovy","strength":"0.25mg","ladderIndex":0}},{"value":"wegovy_0.5mg","label":"Wegovy 0.5mg","metadata":{"medicine":"Wegovy","strength":"0.5mg","ladderIndex":1}},{"value":"wegovy_1mg","label":"Wegovy 1mg","metadata":{"medicine":"Wegovy","strength":"1mg","ladderIndex":2}},{"value":"wegovy_1.7mg","label":"Wegovy 1.7mg","metadata":{"medicine":"Wegovy","strength":"1.7mg","ladderIndex":3}},{"value":"wegovy_2.4mg","label":"Wegovy 2.4mg","metadata":{"medicine":"Wegovy","strength":"2.4mg","ladderIndex":4}}]},{"id":"doseRequest","type":"select","label":"Is this a starting dose, or a change?","required":true,"presentation":"radioList","options":[{"value":"starting","label":"Starting dose"},{"value":"same","label":"Stay on the same dose"},{"value":"increase","label":"Increase dose"},{"value":"decrease","label":"Decrease dose"}]},{"id":"supplyDuration","type":"select","label":"How much supply are you asking for?","helpText":"One month is one pen — four doses, one a week.","required":true,"presentation":"segmented","options":[{"value":"1","label":"1 pen (4 weeks)"},{"value":"2","label":"2 pens (8 weeks)"}]},{"id":"collectionBranch","type":"select","label":"Where would you like to collect?","required":true,"presentation":"segmented","storeMetadataAs":"collectionBranchDetail","options":[{"value":"2e9d53ca-ce0a-50a3-9ad0-e639a45741b2","label":"Onchan","metadata":{"branchId":"2e9d53ca-ce0a-50a3-9ad0-e639a45741b2"}},{"value":"91d6d112-e3c0-5676-8b3c-029428a17e97","label":"Kirk Michael","metadata":{"branchId":"91d6d112-e3c0-5676-8b3c-029428a17e97"}}]}]},{"id":"evidence-safety","title":"Evidence and safety","fields":[{"id":"evidence","type":"fileUpload","label":"Photo of a previous prescription or medicine box","helpText":"Only needed if you are not starting on the lowest dose. JPG, PNG or PDF."},{"id":"pregnancy","type":"yesNo","label":"Are you pregnant, breastfeeding, or planning a pregnancy?","required":true,"presentation":"pills","visibleWhen":[{"field":"gender","operator":"neq","value":"male"}],"warnWhen":[{"value":"yes","severity":"stop","message":"This treatment cannot be supplied during pregnancy, breastfeeding, or while planning a pregnancy. Please speak to a pharmacist."}]},{"id":"oralContraception","type":"yesNo","label":"Are you taking oral contraception (the pill)?","required":true,"presentation":"pills","visibleWhen":[{"field":"gender","operator":"neq","value":"male"}],"warnWhen":[{"value":"yes","severity":"warn","message":"This medicine can slow digestion, which may affect how well the pill is absorbed. A pharmacist will discuss this with you."}]},{"id":"bleedingDisorder","type":"yesNo","label":"Do you have a bleeding disorder?","required":true,"presentation":"pills","visibleWhen":[{"field":"gender","operator":"eq","value":"male"}]},{"id":"anythingElse","type":"yesNo","label":"Is there anything else we should know?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"anythingElseDetail","type":"longText","label":"Please tell us","required":true}]}]}]},{"id":"consent","title":"Consent","fields":[{"id":"consent","type":"consentList","label":"Consent to treatment","required":true},{"id":"signature","type":"signature","label":"Please sign below","required":true}]}]}'::jsonb, now())
on conflict (id) do nothing;

