insert into form_version (id, organisation_id, service_id, version, schema, published_at) values
  ('5265a0fd-6ae1-54e3-9c31-ad61133d7efe', 'e91b8b9a-54e8-55a1-8412-d3ade3da0b53', '28faaa7f-5cf1-519a-8b1d-fd1d72188ee4', 1, '{"schemaVersion":1,"title":"Weight Management — Repeat Request","description":"A short check-in so we can supply your next pen safely. About four minutes.","numberQuestions":true,"estimatedMinutes":4,"consentClauses":[{"id":"risks","text":"I have received information on the risks and benefits of the medicine, and I have had the opportunity to ask questions."},{"id":"accurate","text":"The medical information I have provided is true and accurate to the best of my knowledge, and I consent to the medicine being supplied."},{"id":"reliance","text":"I understand that the supply of this medicine is based on the information I have given, and that if it is inaccurate it could negatively affect my treatment."},{"id":"appointment","text":"I understand that I can make an appointment to see a pharmacist in person at any time to discuss my treatment."},{"id":"storage","text":"I understand that my personal information — name, surname, email, telephone, date of birth, address and GP details — will be securely stored and processed in line with data protection regulations."},{"id":"transmission","text":"I authorise the collection, storage, and secure transmission of my information for the purposes mentioned above."},{"id":"gp","text":"I acknowledge that my GP will be notified of any prescription issued."},{"id":"rights","text":"I understand I can speak to a member of staff about any queries regarding my consultation or the processing of my personal data, by contacting the pharmacy."}],"clinicianDeclarations":[{"id":"accurate","text":"I confirm the patient has provided accurate information and disclosed all medical conditions and allergies."},{"id":"leaflet","text":"I confirm I have provided a patient information leaflet and discussed as required."},{"id":"side-effects","text":"I confirm I have advised the patient on possible side effects and their management."},{"id":"pregnancy-suspected","text":"I have made the patient aware they should discontinue treatment and contact their supplier or GP if they suspect pregnancy."},{"id":"pregnancy-planned","text":"I have made the patient aware they should contact their supplier if planning pregnancy, as treatment must be discontinued."},{"id":"contraception","text":"I confirm the patient has been advised regarding contraception interactions and risks related to delayed gastric emptying."},{"id":"insulin","text":"I confirm the patient has received GP advice if also taking insulin or sulfonylureas, with monitoring in place."}],"steps":[{"id":"how","title":"How would you like to proceed?","fields":[{"id":"consultType","type":"select","label":"How would you like to proceed?","required":true,"presentation":"segmented","options":[{"value":"online","label":"Complete online"},{"value":"clinic","label":"Visit the clinic"}],"warnWhen":[{"value":"clinic","severity":"info","message":"No problem — finish this form and we will book you in rather than supplying online."}]}]},{"id":"progress","title":"How you are getting on","description":"Your height is carried over — only change it if it is wrong.","fields":[{"id":"height","type":"measurement","label":"Height","measurementKind":"height","required":true},{"id":"weight","type":"measurement","label":"Current weight","measurementKind":"weight","required":true},{"id":"waist","type":"measurement","label":"Current waist","measurementKind":"length","required":true},{"id":"bmi","type":"derived","label":"Calculated BMI","calculation":"bmi","calculationInputs":["weight","height"]},{"id":"weightLostThisMonth","type":"number","label":"Roughly how much weight have you lost since your last supply?","helpText":"In kilograms. Enter 0 if none.","required":true,"validation":{"min":0,"max":30,"message":"Enter a figure between 0 and 30 kg."}}]},{"id":"medication","title":"Your medicine","fields":[{"id":"historyChanged","type":"yesNo","label":"Has your medication or medical history changed since your last supply?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"historyChangedDetail","type":"longText","label":"What has changed?","required":true}]}]},{"id":"currentMedicine","type":"select","label":"What are you currently taking?","required":true,"presentation":"dropdown","storeMetadataAs":"currentMedicineDetail","options":[{"value":"mounjaro_2.5mg","label":"Mounjaro 2.5mg","metadata":{"medicine":"Mounjaro","strength":"2.5mg","ladderIndex":0}},{"value":"mounjaro_5mg","label":"Mounjaro 5mg","metadata":{"medicine":"Mounjaro","strength":"5mg","ladderIndex":1}},{"value":"mounjaro_7.5mg","label":"Mounjaro 7.5mg","metadata":{"medicine":"Mounjaro","strength":"7.5mg","ladderIndex":2}},{"value":"mounjaro_10mg","label":"Mounjaro 10mg","metadata":{"medicine":"Mounjaro","strength":"10mg","ladderIndex":3}},{"value":"mounjaro_12.5mg","label":"Mounjaro 12.5mg","metadata":{"medicine":"Mounjaro","strength":"12.5mg","ladderIndex":4}},{"value":"mounjaro_15mg","label":"Mounjaro 15mg","metadata":{"medicine":"Mounjaro","strength":"15mg","ladderIndex":5}},{"value":"wegovy_0.25mg","label":"Wegovy 0.25mg","metadata":{"medicine":"Wegovy","strength":"0.25mg","ladderIndex":0}},{"value":"wegovy_0.5mg","label":"Wegovy 0.5mg","metadata":{"medicine":"Wegovy","strength":"0.5mg","ladderIndex":1}},{"value":"wegovy_1mg","label":"Wegovy 1mg","metadata":{"medicine":"Wegovy","strength":"1mg","ladderIndex":2}},{"value":"wegovy_1.7mg","label":"Wegovy 1.7mg","metadata":{"medicine":"Wegovy","strength":"1.7mg","ladderIndex":3}},{"value":"wegovy_2.4mg","label":"Wegovy 2.4mg","metadata":{"medicine":"Wegovy","strength":"2.4mg","ladderIndex":4}}]},{"id":"weeksOnDose","type":"select","label":"How many weeks have you been on this strength?","required":true,"presentation":"dropdown","options":[{"value":"1","label":"1 week"},{"value":"2","label":"2 weeks"},{"value":"3","label":"3 weeks"},{"value":"4","label":"4 weeks"},{"value":"5","label":"5 weeks"},{"value":"6","label":"6 weeks"},{"value":"7","label":"7 weeks"},{"value":"8","label":"8 weeks"},{"value":"9","label":"9 weeks"},{"value":"10","label":"10 weeks"},{"value":"11","label":"11 weeks"},{"value":"12","label":"12 weeks"},{"value":"13","label":"13 weeks"},{"value":"14","label":"14 weeks"},{"value":"15","label":"15 weeks"},{"value":"16","label":"16 weeks"},{"value":"17","label":"17 weeks"},{"value":"18","label":"18 weeks"},{"value":"19","label":"19 weeks"},{"value":"20","label":"20 weeks"},{"value":"21","label":"21 weeks"},{"value":"22","label":"22 weeks"},{"value":"23","label":"23 weeks"},{"value":"24","label":"24 weeks"},{"value":"25","label":"25 weeks"},{"value":"26","label":"26 weeks"},{"value":"27","label":"27 weeks"},{"value":"28","label":"28 weeks"},{"value":"29","label":"29 weeks"},{"value":"30","label":"30 weeks"},{"value":"31","label":"31 weeks"},{"value":"32","label":"32 weeks"},{"value":"33","label":"33 weeks"},{"value":"34","label":"34 weeks"},{"value":"35","label":"35 weeks"},{"value":"36","label":"36 weeks"},{"value":"37","label":"37 weeks"},{"value":"38","label":"38 weeks"},{"value":"39","label":"39 weeks"},{"value":"40","label":"40 weeks"},{"value":"41","label":"41 weeks"},{"value":"42","label":"42 weeks"},{"value":"43","label":"43 weeks"},{"value":"44","label":"44 weeks"},{"value":"45","label":"45 weeks"},{"value":"46","label":"46 weeks"},{"value":"47","label":"47 weeks"},{"value":"48","label":"48 weeks"},{"value":"49","label":"49 weeks"},{"value":"50","label":"50 weeks"},{"value":"50+","label":"More than 50 weeks"}]},{"id":"missedDoses","type":"select","label":"How many doses have you missed in the last 4 weeks?","required":true,"presentation":"segmented","options":[{"value":"0","label":"None"},{"value":"1","label":"1"},{"value":"2+","label":"2 or more"}]},{"id":"adverseEffects","type":"scale","label":"Have you had any side effects?","required":true,"presentation":"radioList","options":[{"value":"none","label":"None"},{"value":"mild","label":"Mild — manageable, happy to continue"},{"value":"moderate","label":"Moderate — troublesome"},{"value":"severe","label":"Severe"},{"value":"red_flag","label":"Severe stomach pain, persistent vomiting, or yellowing of the skin or eyes"}],"warnWhen":[{"value":"red_flag","severity":"stop","message":"Please stop taking your medicine and contact the pharmacy today."},{"value":"severe","severity":"stop","message":"A pharmacist needs to speak with you before any further supply."}]},{"id":"glp1SideEffects","type":"yesNo","label":"Have you had any side effects specific to your GLP-1 medicine?","required":true,"presentation":"pills","reveals":[{"whenValue":"yes","fields":[{"id":"glp1SideEffectsDetail","type":"longText","label":"Please describe them","required":true}]}]},{"id":"pregnancy","type":"yesNo","label":"Are you pregnant or breastfeeding?","required":true,"presentation":"pills","visibleWhen":[{"field":"gender","operator":"neq","value":"male"}],"warnWhen":[{"value":"yes","severity":"stop","message":"Treatment cannot be supplied. Please stop taking your medicine and contact the pharmacy."}]}]},{"id":"lifestyle","title":"How the treatment is working","description":"These answers are what tell us whether your dose is right.","fields":[{"id":"appetiteSuppression","type":"scale","label":"How well is your appetite being controlled?","required":true,"presentation":"radioList","options":[{"value":"full","label":"Full suppression all week — no hunger between meals"},{"value":"mostly","label":"Mostly suppressed — minor hunger, manageable"},{"value":"wearing_off","label":"Wearing off before my next dose — hungry later in the week"},{"value":"poor","label":"Poor suppression — hungry most days"}]},{"id":"snacking","type":"scale","label":"How would you describe your meals and snacking?","required":true,"presentation":"radioList","options":[{"value":"controlled","label":"Fewer than 3 regular meals, no snacks"},{"value":"occasional","label":"Occasional small snacks, still controlled — fewer than 3 times a week"},{"value":"daily","label":"A daily snacking habit creeping back in — more than 3 times a week"},{"value":"frequent","label":"Frequent snacking or grazing, almost every day"}]},{"id":"hydration","type":"scale","label":"How much water are you drinking each day?","required":true,"presentation":"radioList","options":[{"value":"high","label":"2 litres or more"},{"value":"adequate","label":"1.5 to 1.9 litres"},{"value":"low","label":"1 to 1.4 litres"},{"value":"very_low","label":"Less than 1 litre"}]},{"id":"focusArea","type":"select","label":"What would you like to focus on this month?","helpText":"Pick one. We will tailor your advice around it.","required":true,"presentation":"radioList","options":[{"value":"eating_habits","label":"Eating habits — timing and portion control"},{"value":"nutrition","label":"Diet and nutrition — protein, fibre, balance"},{"value":"activity","label":"Physical activity and exercise"},{"value":"sleep_stress","label":"Sleep, stress and emotional health"},{"value":"support","label":"Social support and routines"}]}]},{"id":"request","title":"Your request","fields":[{"id":"doseRequest","type":"select","label":"What would you like to do with your dose?","required":true,"presentation":"segmented","options":[{"value":"same","label":"Stay the same"},{"value":"increase","label":"Increase"},{"value":"decrease","label":"Decrease"}]},{"id":"supplyQuantity","type":"select","label":"How much would you like?","required":true,"presentation":"segmented","options":[{"value":"1","label":"1 pen (4 weeks)"},{"value":"2","label":"2 pens (8 weeks)"},{"value":"3","label":"3 pens (12 weeks)"}]},{"id":"collectionBranch","type":"select","label":"Where would you like to collect?","required":true,"presentation":"segmented","storeMetadataAs":"collectionBranchDetail","options":[{"value":"2e9d53ca-ce0a-50a3-9ad0-e639a45741b2","label":"Onchan","metadata":{"branchId":"2e9d53ca-ce0a-50a3-9ad0-e639a45741b2"}},{"value":"91d6d112-e3c0-5676-8b3c-029428a17e97","label":"Kirk Michael","metadata":{"branchId":"91d6d112-e3c0-5676-8b3c-029428a17e97"}}]},{"id":"questionsForPharmacist","type":"longText","label":"Anything you would like to ask or tell the pharmacist?","helpText":"If you ask something here, we will make sure someone speaks to you when you collect."}]},{"id":"consent","title":"Evidence and consent","fields":[{"id":"evidence","type":"fileUpload","label":"Photo of your current medicine box","helpText":"Optional, but it helps us confirm your strength. JPG, PNG or PDF."},{"id":"consent","type":"consentList","label":"Consent to continue treatment","required":true}]}]}'::jsonb, now())
