update service set published_form_version_id = '5265a0fd-6ae1-54e3-9c31-ad61133d7efe' where id = '28faaa7f-5cf1-519a-8b1d-fd1d72188ee4';

-- 24 clinical rules, from the client's decision matrix
insert into ruleset_version (id, organisation_id, service_id, version, definition, published_at) values
  ('4012113a-9e92-5b02-afef-511b0b1ebeb7', 'e91b8b9a-54e8-55a1-8412-d3ade3da0b53', '28faaa7f-5cf1-519a-8b1d-fd1d72188ee4', 1, '{"schemaVersion":1,"defaultOutcome":"AMBER","rules":[{"id":"pregnancy","label":"Pregnant or breastfeeding","priority":1000,"outcome":"RED","when":{"field":"answers.pregnancy","op":"eq","value":"yes"},"message":"Pregnancy or breastfeeding declared. Treatment must be discontinued.","patientMessage":"We cannot supply this treatment at the moment. Please stop taking your medicine and contact the pharmacy."},{"id":"age-wegovy","label":"Wegovy outside the 18–74 age range","priority":990,"outcome":"RED","when":{"all":[{"field":"derived.medicine","op":"eq","value":"Wegovy"},{"any":[{"field":"derived.age","op":"lt","value":18},{"field":"derived.age","op":"gt","value":74}]}]},"message":"Outside the licensed age range for Wegovy (18–74)."},{"id":"age-mounjaro","label":"Mounjaro outside the 18–84 age range","priority":990,"outcome":"RED","when":{"all":[{"field":"derived.medicine","op":"eq","value":"Mounjaro"},{"any":[{"field":"derived.age","op":"lt","value":18},{"field":"derived.age","op":"gt","value":84}]}]},"message":"Outside the licensed age range for Mounjaro (18–84)."},{"id":"adverse-severe","label":"Severe adverse effects or red-flag symptoms","priority":960,"outcome":"RED","when":{"field":"answers.adverseEffects","op":"in","value":["severe","red_flag"]},"message":"Severe or red-flag adverse effects reported. Do not supply; contact the patient.","patientMessage":"Please stop taking your medicine and contact the pharmacy today so we can talk this through."},{"id":"missed-two-plus","label":"Two or more doses missed in the past 4 weeks","priority":950,"outcome":"RED","when":{"field":"derived.missedDoses","op":"gte","value":2},"message":"Two or more doses missed. Adherence and re-titration need reviewing in person."},{"id":"dose-skip","label":"Dose change skipping more than one strength","priority":940,"outcome":"RED","when":{"any":[{"field":"derived.doseStepChange","op":"gt","value":1},{"field":"derived.doseStepChange","op":"lt","value":-1}]},"message":"Requested change is more than one step on the ladder. Only same or ±1 is permitted."},{"id":"bmi-low-not-decreasing","label":"BMI under 23 and not requesting a decrease","priority":930,"outcome":"RED","when":{"all":[{"field":"derived.bmi","op":"lt","value":23},{"field":"answers.doseRequest","op":"neq","value":"decrease"}]},"message":"BMI is below 23 and the patient is not tapering. Needs review in person."},{"id":"bmi-low-tapering","label":"BMI under 23 with a decrease request (tapering)","priority":920,"outcome":"GREEN","when":{"all":[{"field":"derived.bmi","op":"lt","value":23},{"field":"answers.doseRequest","op":"eq","value":"decrease"}]},"message":"Tapering at a healthy BMI. Appropriate to support.","advice":"Congratulations on reaching a healthy weight. Reducing your dose gradually is the right way to come off treatment — speak to us if you are unsure."},{"id":"bmi-borderline","label":"BMI between 23 and 24.9","priority":700,"outcome":"AMBER","when":{"field":"derived.bmi","op":"between","range":[23,24.9]},"message":"BMI is in the 23–24.9 band. Confirm continuing treatment remains appropriate."},{"id":"dose-change-too-soon","label":"Dose change requested before 3 weeks on the current strength","priority":690,"outcome":"AMBER","when":{"all":[{"field":"answers.doseRequest","op":"in","value":["increase","decrease"]},{"field":"derived.weeksOnDose","op":"lt","value":3}]},"message":"Fewer than three weeks on the current strength. Confirm the change is appropriate."},{"id":"supply-two-pens-unstable","label":"Two pens requested without 6 weeks stable on the dose","priority":680,"outcome":"AMBER","when":{"all":[{"field":"answers.supplyQuantity","op":"eq","value":"2"},{"field":"derived.weeksOnDose","op":"lt","value":6}]},"message":"Eight weeks requested before six weeks stable on this dose."},{"id":"supply-three-pens","label":"More than two months of supply requested","priority":675,"outcome":"AMBER","when":{"field":"answers.supplyQuantity","op":"eq","value":"3"},"message":"Twelve weeks requested. Confirm the reason — travel, or established stability."},{"id":"adverse-moderate","label":"Moderate adverse effects","priority":670,"outcome":"AMBER","when":{"field":"answers.adverseEffects","op":"eq","value":"moderate"},"message":"Moderate adverse effects. Consider a dose reduction for tolerability.","advice":"Consider whether a lower strength would be better tolerated."},{"id":"missed-one","label":"One dose missed in the past 4 weeks","priority":660,"outcome":"AMBER","when":{"field":"derived.missedDoses","op":"eq","value":1},"message":"One dose missed. Check the reason before supplying.","advice":"Try to take your dose on the same day each week — a phone reminder helps."},{"id":"history-changed","label":"Medicines or health conditions changed since last supply","priority":650,"outcome":"AMBER","when":{"field":"answers.historyChanged","op":"eq","value":"yes"},"message":"Patient reports a change to medicines or health. Review before supplying."},{"id":"poor-response","label":"Poor suppression or frequent snacking","priority":640,"outcome":"AMBER","when":{"any":[{"field":"answers.appetiteSuppression","op":"in","value":["wearing_off","poor"]},{"field":"answers.snacking","op":"in","value":["daily","frequent"]}]},"message":"Treatment response is dropping off. The answers support considering an increase.","advice":"Focus on protein at each meal and keep portions controlled — this helps most when appetite control is fading."},{"id":"weight-loss-below-target","label":"Weight loss below the 2% monthly target","priority":630,"outcome":"AMBER","when":{"field":"derived.weightLossPercent","op":"lt","value":2},"message":"Under the 2% monthly target. Consider whether the dose is right."},{"id":"patient-question","label":"Patient has asked a question","priority":620,"outcome":"AMBER","when":{"field":"answers.questionsForPharmacist","op":"exists"},"message":"The patient has asked something. Make sure they are spoken to at collection."},{"id":"wants-clinic","label":"Patient asked to visit the clinic","priority":610,"outcome":"AMBER","when":{"field":"answers.consultType","op":"eq","value":"clinic"},"message":"Patient chose to be seen rather than supplied online. Book them in."},{"id":"stable-continue","label":"Stable on the same dose and meeting target","priority":500,"outcome":"GREEN","when":{"all":[{"field":"answers.doseRequest","op":"eq","value":"same"},{"field":"answers.adverseEffects","op":"in","value":["none","mild"]},{"field":"derived.missedDoses","op":"eq","value":0},{"field":"derived.weeksOnDose","op":"gte","value":3},{"field":"derived.bmi","op":"gte","value":25},{"field":"derived.weightLossPercent","op":"gte","value":2},{"field":"answers.appetiteSuppression","op":"in","value":["full","mostly"]},{"field":"answers.snacking","op":"in","value":["controlled","occasional"]},{"field":"answers.historyChanged","op":"eq","value":"no"}]},"message":"No concerns flagged. Continuing the same dose.","advice":"Keep going — you are on track. Aim for 1.5 to 2 litres of water a day."},{"id":"increase-supported","label":"Increase supported by the answers, and eligible on timing","priority":490,"outcome":"GREEN","when":{"all":[{"field":"answers.doseRequest","op":"eq","value":"increase"},{"field":"derived.doseStepChange","op":"eq","value":1},{"field":"derived.weeksOnDose","op":"gte","value":3},{"field":"answers.adverseEffects","op":"in","value":["none","mild"]},{"field":"derived.missedDoses","op":"eq","value":0},{"field":"derived.bmi","op":"gte","value":25},{"field":"answers.historyChanged","op":"eq","value":"no"}]},"message":"Meets criteria for an increase — confirm?"},{"id":"hydration-low","label":"Low fluid intake","priority":100,"outcome":"GREEN","when":{"field":"answers.hydration","op":"in","value":["low","very_low"]},"advice":"Try to drink at least 1.5 to 2 litres of water a day. It helps with constipation, headaches and dizziness, which are common on this medicine."},{"id":"hydration-good","label":"Good fluid intake","priority":90,"outcome":"GREEN","when":{"field":"answers.hydration","op":"eq","value":"high"},"advice":"Your fluid intake is where we want it — keep that up."},{"id":"mild-effects-advice","label":"Mild adverse effects","priority":80,"outcome":"GREEN","when":{"field":"answers.adverseEffects","op":"eq","value":"mild"},"advice":"Mild nausea usually settles. Smaller meals, eating slowly, and avoiding fatty food all help."}]}'::jsonb, now())
on conflict (id) do nothing;

update service set published_ruleset_version_id = '4012113a-9e92-5b02-afef-511b0b1ebeb7' where id = '28faaa7f-5cf1-519a-8b1d-fd1d72188ee4';

commit;
